package org.sleepwell.app;
import java.time.*;import java.util.*;
/** An engineering reminder calculation, not a sleep-debt diagnosis or sleep guarantee. */
final class SmartBedtime {
 interface Projection{long next(Alarm a,long now,ZoneId zone);}
 static final class Result {
  final long at,alarmAt,shortfall;final int alarmId,smart,delay,adjustment,observed;final boolean fallback;final String issue,identity,proof;
  Result(long at,long alarmAt,int alarmId,int smart,int delay,int adjustment,int observed,long shortfall,boolean fallback,String issue,SleepPlan p,ZoneId zone){this.at=at;this.alarmAt=alarmAt;this.alarmId=alarmId;this.smart=smart;this.delay=delay;this.adjustment=adjustment;this.observed=observed;this.shortfall=shortfall;this.fallback=fallback;this.issue=issue;identity=fallback?"fixed:"+Instant.ofEpochMilli(at).atZone(zone).toLocalDate():"alarm:"+alarmId+":"+alarmAt;proof=identity+":"+at+":"+p.revision+":"+p.goal+":"+p.reminderAdvance+":"+p.smartBedtime+":"+p.noAlarmBedtime+":"+p.smartRepeatMinutes+":"+p.smartRepeatLimit+":"+smart+":"+delay+":"+adjustment+":"+observed+":"+shortfall+":"+zone.getId();}
 }
 static Result calculate(SleepPlan p,List<Alarm> alarms,List<RecordEntry> records,long now,ZoneId zone,int delay,Projection projection){p.validate();if(!TrackingDelay.allowed(delay))throw new IllegalArgumentException("Review the saved tracking delay.");LocalDate today=SleepDay.label(now,zone,720);Map<LocalDate,List<RecordIntervals.Span>> days=new TreeMap<>();List<RecordIntervals.Span> claimed=new ArrayList<>();List<RecordEntry> ordered=new ArrayList<>(records);ordered.sort(Comparator.comparingLong((RecordEntry r)->r.rawStart).thenComparingLong(r->r.id));for(RecordEntry r:ordered){if(!recorded(r,now))continue;LocalDate date=SleepDay.label(r.edit.end,zone,720);if(date.isBefore(today.minusDays(4))||date.isAfter(today))continue;List<RecordIntervals.Span> unique=RecordIntervals.subtract(r.coverage(),claimed);claimed.addAll(unique);claimed=RecordIntervals.union(claimed);if(!unique.isEmpty())days.computeIfAbsent(date,k->new ArrayList<>()).addAll(unique);}long total=0;for(List<RecordIntervals.Span> day:days.values())total+=RecordIntervals.length(day);long shortfall=days.isEmpty()?0:p.goal*60000L-total/days.size();int extra=shortfall>10*60000L?(int)Math.min(45,(shortfall+59999)/60000):0;
  Alarm chosen=null;long next=Long.MAX_VALUE;for(Alarm alarm:alarms){if(!alarm.enabled||alarm.nap!=null||alarm.napInvalid||alarm.skipInvalid||alarm.dateInvalid||alarm.solarInvalid)continue;long projected=projection.next(alarm,now,zone);if(projected>now&&(projected<next||projected==next&&(chosen==null||alarm.id<chosen.id))){chosen=alarm;next=projected;}}
  if(chosen==null){if(p.noAlarmBedtime){long fixed=p.nextReminder(now,zone);return new Result(fixed,0,0,0,0,0,days.size(),shortfall,true,"",p,zone);}return new Result(0,0,0,0,delay,extra,days.size(),shortfall,false,"No eligible upcoming alarm. Fixed fallback is off.",p,zone);}
  int smart=Math.max(0,chosen.smartWindow);long at=next-(p.goal+(long)smart+delay+extra+p.reminderAdvance)*60000L;return new Result(at,next,chosen.id,smart,delay,extra,days.size(),shortfall,false,"",p,zone);
 }
 private static boolean recorded(RecordEntry r,long now){return r.source.equals("tracked")&&Set.of("local","imported").contains(r.origin)&&r.interrupted==0&&r.clockChanged==0&&r.rawStart>0&&r.rawEnd>r.rawStart&&r.rawEnd<=now&&r.rawEnd-r.rawStart<=36*3600000L&&r.active!=null&&r.active>0&&r.active<=r.rawEnd-r.rawStart&&r.edit.start>=r.rawStart&&r.edit.end<=r.rawEnd&&r.edit.end>r.edit.start&&r.healthConnect.isEmpty()&&(r.sensor.equals("accelerometer")||r.sensor.equals("sonar_fmcw_v1"))&&r.edit.tags.stream().noneMatch(t->t.equalsIgnoreCase("nap"));}
 private SmartBedtime(){}
}
